import{_ as e,o as a,c as o,a2 as i}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Floating","description":"","frontmatter":{},"headers":[],"relativePath":"components/floating.md","filePath":"components/floating.md"}'),n={name:"components/floating.md"};function s(r,t,d,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="floating" tabindex="-1">Floating <a class="header-anchor" href="#floating" aria-label="Permalink to &quot;Floating&quot;">​</a></h1><p>Floating is a container that floats over the stage.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for what floats over the stage: a search, the navigation, a credit line, a small floating pane. A panel beside the stage is a <a href="./panel">Panel</a>. It takes only its position from outside. Without a position it stands in the flow of a place that is already positioned, such as the content of a <a href="./dropdown">Dropdown</a> with <code>bare</code>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>top</code></td><td></td><td>The distance to the top: a gap step, 0 or a length</td></tr><tr><td><code>right</code></td><td></td><td>The distance to the right, likewise</td></tr><tr><td><code>bottom</code></td><td></td><td>The distance to the bottom, likewise</td></tr><tr><td><code>left</code></td><td></td><td>The distance to the left, likewise</td></tr><tr><td><code>children</code></td><td>required</td><td>The content</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It has the panel color and one strong line, no shadow, and floats on the floating layer. It is placed absolutely in its frame, which must be a positioned element; a step name (<code>2xs</code> to <code>xl</code>) is that gap step, and any other string is a CSS length. Pinned, it is no wider than the frame less the left and right sides given as steps (or 0); a side given as another length is the application&#39;s own and is not subtracted. Two Floatings that would overlap are the application&#39;s layout to solve. With no side given it stands in the flow, fills its place and stacks its content in a column, so that text wraps inside the frame. It has no padding: list items hold their own, and text goes in a <a href="./block">Block</a>. A control without a line or a surface placed directly in it (a ghost button, alone or in a <a href="./row">Row</a> as a bar) is laid out at its reach, the height of a small button, and keeps its width, so the Floating holds its whole hit area and its line never cuts it. In a browser without container style queries (Firefox before 151) the hit area reaches across the line instead; it is still pressed as a whole.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/floating/" title="Floating" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/floating/" target="_blank" rel="noopener">Floating</a></figcaption></figure>',10)])])}const g=e(n,[["render",s]]);export{f as __pageData,g as default};
